using System.Text;

namespace Velora.Localization;

public static class LocalizationKey
{
    private const int MaximumNormalizedTextLength = 50;

    /// <summary>
    /// Reproduces the compatibility-era key generated by the C++ localizer.
    /// Only ASCII letters and digits survive normalization; spaces become
    /// single underscores and the normalized text is limited to 50 bytes.
    /// </summary>
    public static string Generate(string text, string context = "", string speaker = "")
    {
        ArgumentNullException.ThrowIfNull(text);
        ArgumentNullException.ThrowIfNull(context);
        ArgumentNullException.ThrowIfNull(speaker);

        byte[] utf8 = Encoding.UTF8.GetBytes(text);
        StringBuilder normalizedPrefix = new(Math.Min(utf8.Length, MaximumNormalizedTextLength));
        int normalizedLength = 0;
        int lengthWithoutTrailingUnderscores = 0;
        byte lastNormalized = 0;

        foreach (byte value in utf8)
        {
            byte normalizedValue = 0;
            if (value is >= (byte)'A' and <= (byte)'Z')
            {
                normalizedValue = (byte)(value + ('a' - 'A'));
            }
            else if (value is >= (byte)'a' and <= (byte)'z' or >= (byte)'0' and <= (byte)'9')
            {
                normalizedValue = value;
            }
            else if (value == (byte)' ' && normalizedLength > 0 && lastNormalized != (byte)'_')
            {
                normalizedValue = (byte)'_';
            }

            if (normalizedValue == 0)
            {
                continue;
            }

            if (normalizedPrefix.Length < MaximumNormalizedTextLength)
            {
                normalizedPrefix.Append((char)normalizedValue);
            }

            normalizedLength++;
            lastNormalized = normalizedValue;
            if (normalizedValue != (byte)'_')
            {
                lengthWithoutTrailingUnderscores = normalizedLength;
            }
        }

        normalizedPrefix.Length = Math.Min(lengthWithoutTrailingUnderscores, MaximumNormalizedTextLength);

        StringBuilder key = new(context.Length + speaker.Length + normalizedPrefix.Length + 2);
        if (context.Length > 0)
        {
            key.Append(context).Append('.');
        }

        if (speaker.Length > 0)
        {
            key.Append(speaker).Append('.');
        }

        key.Append(normalizedPrefix);
        return key.ToString();
    }
}
